mapper.select:
select c.id,c.`name`,c.code,c.category_id,c.brand,c.model,c.goods_code,c.unit,c.quality_period, c.stock_max,c.stock_min,c.use_limit,c.stock,c.amount,cd.num,ss.position,ss.store_id, cd.check_num as checkNum,cc.id as checkId,cd.status,cd.checker_name,cd.check_time from consumable_check cc inner join consumable_store_stock ss on cc.store_id = ss.store_id inner join consumable_check_detail cd on cd.check_id = cc.id inner join consumable c on ss.consumable_id = c.id and cd.consumable_id=c.id where cc.id = #{param.checkId}
and (c.name like concat("%",#{param.keyword},"%") or c.code like concat("%",#{param.keyword},"%"))
and c.category_id = #{param.categoryId}
GROUP BY c.id
